    if (el.level && lv !== hudLast.level) { hudLast.level = lv; el.level.textContent = lv; }
    const e = Math.max(0, Math.round(game.energy));
    if (e !== hudLast.energy) {
      hudLast.energy = e;
      if (el.energy) el.energy.textContent = e;
      if (el.energyBar) el.energyBar.style.width = e + '%';
    }
    const low = e <= 30;
    if (el.energyBar && low !== hudLast.low) { hudLast.low = low; el.energyBar.style.background = low ? '#ff6b6b' : 'linear-gradient(90deg,#2fbf63,#7dff9a)'; }
    const tv = (game.boss && !game.boss.dead) ? 'BOSS' : left;
